import assert from 'node:assert/strict';
import test from 'node:test';
import { execute } from '../../packages/safe-bash/tests/commands/core-regression-stress/helpers.js';
import { createMemoryFileSystem } from '../../packages/safe-bash/src/fs/memory/index.js';

for (const args of [['--check', '--raw'], ['--raw', '--check'], ['-a', 'md5', '--check', '--raw'], ['--raw', '--check', '-a', 'md5']]) {
  for (const text of ['secret', '900150983cd24fb0d6963f7d28e17f72  data\n']) {
    test(`invalid combination refuses input ${args.join(' ')} ${text.length}`, async () => {
      let pulls = 0;
      const stdin = (async function* () { pulls++; yield Buffer.from(text); })();
      const result = await execute('cksum', args, { stdin });
      assert.equal(result.exitCode, 2);
      assert.equal(pulls, 0);
      assert.equal(result.stdout.length, 0);
    });
  }
}

for (const args of [['--check'], ['--check', '-'], ['--check', '--', '-']]) {
  for (const text of ['secret', '']) {
    test(`supported verification consumes manifest ${args.join(' ')} ${text.length}`, async () => {
      let pulls = 0;
      const stdin = (async function* () { pulls++; yield Buffer.from(text); })();
      const result = await execute('cksum', args, { stdin });
      assert.equal(result.exitCode, 1);
      assert.equal(pulls, 1);
      assert.equal(result.stdout.length, 0);
      assert.equal(result.stderr.toString(), 'cksum: -: no properly formatted checksum lines found\n');
    });
  }
}

for (const args of [['--check', '-a', 'md5'], ['-a', 'md5', '--check']]) {
  test(`supported verification reads a valid manifest ${args.join(' ')}`, async () => {
    const fs = createMemoryFileSystem();
    await fs.mkdir('/work');
    await fs.writeFile('/work/data', Buffer.from('abc'));
    let pulls = 0;
    const stdin = (async function* () { pulls++; yield Buffer.from('900150983cd24fb0d6963f7d28e17f72  data\n'); })();
    const result = await execute('cksum', args, { stdin, fs });
    assert.equal(result.exitCode, 0);
    assert.equal(pulls, 1);
    assert.equal(result.stdout.toString(), 'data: OK\n');
    assert.equal(result.stderr.length, 0);
  });
}
